xit'?p.z<80:p.z>82.15&&p.z<84&&Math.abs(p.x-6.6)<.5&&p.y>=67;if(!ok)throw Error('DOOR_NOT_ARRIVED');console.log('DOOR_ACTUAL',mode,p.toString());}finally{bot.clearControlStates();if(!dead&&!lost&&bot.game.dimension==='overworld')for(const x of[6,7]){const b=bot.blockAt(new Vec3(x,67,81));if(b?.name==='spruce_door'&&b.getProperties().open&&bot.entity.position.distanceTo(b.position.offset(.5,.5,.5))<4.5){try{await bot.activateBlock(b);await bot.waitForTicks(3);}catch(e){console.log('DOOR_CLOSE_FAILED',x,e.message);}}}bot.removeListener('entityHurt',damaged);}}


function insideCamp(){const p=bot.entity.position;return bot.game.dimension==='overworld'&&p.x>5.5&&p.x<8&&p.z>82.15&&p.z<84&&p.y>=67&&[6,7].every(x=>{const b=bot.blockAt(new Vec3(x,67,81));return b?.name==='spruce_door'&&b.getProperties().open===false&&b.getProperties().facing==='north'})}
async function landXZ(x,z){check('overworld');const m=new Movements(bot);m.canDig=false;m.allowSprinting=false;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=3;for(const n of['lava','water','nether_portal','fire','magma_block','sweet_berry_bush'])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);bot.pathfinder.setMovements(m);bot.pathfinder.thinkTimeout=1500;let t,error=null;try{await Promise.race([bot.pathfinder.goto(new goals.GoalXZ(x,z)),new Promise((_,r)=>t=setTimeout(()=>{bot.pathfinder.setGoal(null);r(Error('LAND_XZ_BOUND'));},7000))]);}catch(e){error=e;}finally{clearTimeout(t);bot.pathfinder.setGoal(null);bot.clearControlStates();}await ticks(8);const p=bot.entity.position,b=bot.blockAt(p.floored());if(!bot.entity.onGround||Math.hypot(p.x-x-.5,p.z-z-.5)>.7||['water','lava','fire'].includes(b.name))throw error||Error('ACTUAL_LAND_BAD');console.log('LANDED_ACTUAL',x,z,p.toString(),b.name);}
function campThreats(){return Object.values(bot.entities).filter(e=>isHostile(e)&&e.position.x>5.5&&e.position.x<8.3&&e.position.z>81.7&&e.position.z<84.2&&e.position.y>66&&e.position.y<70).map(e=>[e.id,e.name,e.position]);}
function safeCamp(){return !dead&&!lost&&insideCamp()&&bot.entity.onGround&&campThreats().length===0;}
async function returnCamp(){retreat=true;if(!dead&&!lost&&!insideCamp()){await landXZ(6,79);await door('enter');}await ticks(8);if(!safeCamp())throw Error('CAMP_POSTCONDITION '+JSON.stringify(campThreats()));}
function cleanup(){bot.clearControlStates();bot.pathfinder.setGoal(null);bot.removeListener('death',death);bot.removeListener('respawn',respawn);}
const refugeFoot=new Vec3(21,65,88),refugeCap=refugeFoot.offset(0,2,0);
function refugeHull(){return full(bot.blockAt(refugeFoot.offset(0,-1,0)))&&full(bot.blockAt(refugeCap))&&[[1,0],[-1,0],[0,1],[0,-1]].every(([x,z])=>[0,1].every(y=>full(bot.blockAt(refugeFoot.offset(x,y,z)))));}
async function capRefuge(){if(full(bot.blockAt(refugeCap)))return;const i=['dirt','spruce_planks','cobblestone'].map(n=>bot.inventory.items().find(i=>i.name===n)).find(Boolean);if(!i)throw Error('REFUGE_NO_CAP');const r=refugeCap.offset(1,0,0);if(!full(bot.blockAt(r)))throw Error('REFUGE_REF');await bot.equip(i,'hand');await bot._placeBlockWithOptions(bot.blockAt(r),new Vec3(-1,0,0),{forceLook:true,swingArm:'right'});await ticks(5);if(!full(bot.blockAt(refugeCap)))throw Error('REFUGE_CAP_ACK');}
async function enterRefuge(){check('overworld');if(bot.entity.position.floored().x!==21||bot.entity.position.floored().z!==88)await landXZ(21,88);for(let k=0;k<24&&Math.hypot(bot.entity.position.x-21.5,bot.entity.position.z-88.5)>.065;k++){check();await bot.lookAt(new Vec3(21.5,bot.entity.position.y+1.62,88.5),true);bot.setControlState('sneak',true);bot.setControlState('forward',true);await ticks(1);bot.clearControlStates();await ticks(2);}bot.clearControlStates();if(Math.hypot(bot.entity.position.x-21.5,bot.entity.position.z-88.5)>.13)throw Error('REFUGE_CENTER');while(bot.entity.position.y>65.15){const p=bot.entity.position.floored(),b=bot.blockAt(p.offset(0,-1,0));if(!['dirt','grass_block','spruce_planks'].includes(b.name)||p.y>68)throw Error('REFUGE_CUT_'+b.name);await bot.unequip('hand');await bot.dig(b);await ticks(8);if(Math.abs(bot.entity.position.y-p.y+1)>.15||!bot.entity.onGround)throw Error('REFUGE_DOWN_SETTLE');}await capRefuge();if(!refugeHull()||!bot.entity.onGround||!bot.entity.position.floored().equals(refugeFoot))throw Error('REFUGE_HULL');console.log('REFUGE_FULL_ACTUAL',bot.health,bot.entity.position.toString());}
async function exitRefuge(){check('overworld');if(!refugeHull()||!bot.entity.position.floored().equals(refugeFoot))throw Error('NOT_REFUGE');const b=bot.blockAt(refugeCap);if(!['dirt','grass_block','spruce_planks'].includes(b.name))throw Error('REFUGE_CAP_KIND_'+b.name);await bot.unequip('hand');await bot.dig(b);await ticks(8);for(let k=0;k<3;k++){const p=bot.entity.position.floored(),base=bot.blockAt(p.offset(0,-1,0));const i=['dirt','spruce_planks'].map(n=>bot.inventory.items().find(i=>i.name===n)).find(Boolean);if(!i||!full(base)||bot.blockAt(p.offset(0,2,0)).boundingBox!=='empty')throw Error('REFUGE_UP_RESERVE');await bot.equip(i,'hand');bot.setControlState('jump',true);try{for(let j=0;j<15&&bot.entity.position.y<p.y+1.16;j++)await ticks(1);if(bot.entity.position.y<p.y+1.15)throw Error('REFUGE_UP_HEIGHT');await bot._placeBlockWithOptions(base,new Vec3(0,1,0),{forceLook:true,swingArm:'right'});}finally{bot.setControlState('jump',false);}await ticks(10);if(Math.abs(bot.entity.position.y-p.y-1)>.15||!bot.entity.onGround)throw Error('REFUGE_UP_ACK');}console.log('REFUGE_EXIT_ACTUAL',bot.health,bot.entity.position.toString());}
async function fieldEnding(){retreat=true;try{await returnCamp();protectedEnd=safeCamp();return 'camp';}catch(e){console.log('FIELD_CAMP_FAILED',e.message);await enterRefuge();protectedEnd=refugeHull()&&!dead&&!lost;return 'refuge';}}
let obtained={},qualified=false;const names=['stone_sword','wooden_pickaxe','wooden_shovel','snowball','sweet_berries'];const before=Object.fromEntries(names.map(n=>[n,count(n)]));function threats(p,r){return Object.values(bot.entities).filter(e=>isHostile(e)&&e.position.distanceTo(p)<r).map(e=>[e.id,e.name,e.position]);}
try{if(!safeCamp())throw Error('CAMP_NOT_READY');const plan=[[21,90],[19,92],[24,92]];for(const[x,z]of plan)if(threats(new Vec3(x,68,z),12).length)throw Error('LOOT_THREAT_PRECHECK_'+JSON.stringify(threats(new Vec3(x,68,z),12)));await door('exit');await landXZ(14,79);for(const[x,z]of plan){if(threats(new Vec3(x,68,z),12).length)throw Error('LOOT_DYNAMIC_THREAT');await landXZ(x,z);if(Math.abs(bot.entity.position.y-68)>.25)throw Error('LOOT_WRONG_HEIGHT');await ticks(8);if(count('stone_sword'))await bot.equip(bot.inventory.items().find(i=>i.name==='stone_sword'),'hand');console.log('LOOT_ACTUAL',Object.fromEntries(names.map(n=>[n,count(n)-before[n]])));}obtained=Object.fromEntries(names.map(n=>[n,count(n)-before[n]]));}
catch(e){issue=e.message;console.log('LOOT_ISSUE',issue);}finally{retreat=true;try{if(!dead&&!lost&&insideCamp()){protectedEnd=safeCamp();}else if(!dead&&!lost){await enterRefuge();qualified=refugeHull()&&bot.entity.onGround;protectedEnd=qualified;}}catch(e){console.log('LOOT_END_FAIL',e.message);try{await returnCamp();protectedEnd=safeCamp();}catch(e){console.log('LOOT_ALT_END_FAIL',e.message);}}cleanup();}return{issue,obtained,actual:Object.fromEntries(names.map(n=>[n,count(n)-before[n]])),qualified,protectedEnd,hp:bot.health,food:bot.food,p:bot.entity.position,dead,lost,inv:bot.inventory.items().map(i=>[i.name,i.count]),life:global.P3LifeTracker?{token:[global.P3LifeTracker.started,global.P3LifeTracker.life,global.P3LifeTracker.world],events:global.P3LifeTracker.events}:null};
